  var bs = sc.bars, n = bs.length, a0 = T(sc, sc.show, "start"), at = T(sc, sc.at, "start+0.5"), rc = T(sc, sc.reach, at - sc.s + 1.6), b = T(sc, sc.until, "end+0.3");
