  for (var i = 0; i < ws.length; i++) { if (cur && (cur + " " + ws[i]).length > cols) { lines.push([st, cur]); st = pos; cur = ws[i]; } else cur = cur ? cur + " " + ws[i] : ws[i]; pos += ws[i].length + 1; }
