    KE(mk.shape.property("Size"), tm, 0.5, [0.01, h], [w, h], eioQuart); KE(mk.shape.property("Position"), tm, 0.5, [-w / 2, 0], [0, 0], eioQuart);
    kids.push(mk.l); sfx(tm, "whoosh", 0.12, { d: 0.5 });
