  enterWhoosh(sc, a);
  var x0 = vh(70, 230), x1 = W - x0, top = vh(560, 210), bot = vh(1200, SPEC.captions !== false ? CAP_Y - 150 : H - 110);
  var k = Math.min((x1 - x0) / M.w, (bot - top) / M.h), ox = CX - M.w * k / 2, oy = (top + bot) / 2 - M.h * k / 2;
  function pt(p) { return [ox + p[0] * k, oy + p[1] * k]; }
